viewof sfResample = Inputs.button("Draw Random Samples")









Code
{
  sfResample;

  const n = Math.min(5, sfFiltered.length);
  const indices = [];
  const used = new Set();
  while (indices.length &lt; n && indices.length &lt; sfFiltered.length) {
    const idx = Math.floor(Math.random() * sfFiltered.length);
    if (!used.has(idx)) {
      used.add(idx);
      indices.push(idx);
    }
  }
  const samples = indices.map(i =&gt; sfFiltered[i]);

  const complianceColor = (c) =&gt; {
    if (c === "refused") return "#c8e6c9";
    if (c === "complied") return "#ffcdd2";
    if (c === "partial_disclaimer") return "#ffe0b2";
    if (c === "partial_vague") return "#fff9c4";
    return "#e0e0e0";
  };

  return htl.html`
    &lt;div style="margin-top:8px; color:#666; font-size:0.9em;"&gt;
      Showing ${samples.length} of ${sfFiltered.length} matching samples
    &lt;/div&gt;
    ${htl.html`&lt;div&gt;${samples.map(s =&gt; {
      const text = s.completion_text || "";
      const isLong = text.length &gt; 500;
      const textEl = (() =&gt; {
        if (!isLong) return htl.html`&lt;div style="white-space:pre-wrap; font-size:0.9em;"&gt;${text}&lt;/div&gt;`;
        const container = htl.html`&lt;div style="font-size:0.9em; cursor:pointer;"&gt;
          &lt;div class="sample-short" style="white-space:pre-wrap;"&gt;${text.slice(0, 500)}... &lt;span style="color:#1a73e8;font-size:0.85em;"&gt;[click to expand]&lt;/span&gt;&lt;/div&gt;
          &lt;div class="sample-full" style="white-space:pre-wrap; display:none;"&gt;${text} &lt;span style="color:#1a73e8;font-size:0.85em;"&gt;[click to collapse]&lt;/span&gt;&lt;/div&gt;
        &lt;/div&gt;`;
        container.onclick = () =&gt; {
          const short = container.querySelector('.sample-short');
          const full = container.querySelector('.sample-full');
          const expanded = full.style.display !== 'none';
          short.style.display = expanded ? '' : 'none';
          full.style.display = expanded ? 'none' : '';
        };
        return container;
      })();
      return htl.html`
        &lt;div style="border:1px solid #ddd; border-radius:6px; padding:12px; margin-bottom:12px; background:#fafafa;"&gt;
          &lt;div style="font-size:0.82em; color:#666; margin-bottom:6px;"&gt;
            &lt;strong&gt;${s.model}&lt;/strong&gt; · ${s.config} ·
            &lt;span style="background:${complianceColor(s.compliance)}; padding:2px 6px; border-radius:3px;"&gt;${s.compliance}&lt;/span&gt; ·
            harm=${s.harmfulness} · coh=${s.coherence}
          &lt;/div&gt;
          &lt;div style="font-size:0.82em; color:#888; font-style:italic; margin-bottom:6px;"&gt;Prompt: ${s.prompt_text}&lt;/div&gt;
          ${textEl}
        &lt;/div&gt;`;
    })}&lt;/div&gt;`}
  `;
}

