whereClause = {
  const parts = ["is_valid = true", "localization = 'all'"];
  if (v2Model !== "All") parts.push(`model = '${v2Model}'`);
  if (v2Organism !== "All") parts.push(`organism = '${v2Organism === "base" ? "none" : v2Organism}'`);
  if (v2Weight !== "All") parts.push(`weight = ${Number(v2Weight)}`);
  if (v2Dataset !== "All") parts.push(`dataset = '${v2Dataset}'`);
  if (v2Prompt !== "All") parts.push(`prompt_category = '${v2Prompt}'`);
  if (v2Identity !== "All") parts.push(`identity_claim = '${v2Identity}'`);
  if (v2Fabrication !== "All") parts.push(`experience_fabrication = '${v2Fabrication}'`);
  if (v2Multilingual !== "All") parts.push(`multilingual_contamination = ${v2Multilingual === 'yes'}`);
  parts.push(`(coherence IS NULL OR (coherence &gt;= ${v2CohMin} AND coherence &lt;= ${v2CohMax}))`);
  return parts.join(" AND ");
}
_v2count = db.query(`SELECT COUNT(*) as n FROM v2 WHERE ${whereClause}`)


















