{
  const filtered = id_strat.filter(d =&gt; d.coherence &gt;= minCoherence);
  const orgs = persona_orgs;

  // Helper: aggregate human-specific rate for a subset
  function aggRate(rows) {
    const n = d3.sum(rows, r =&gt; r.n);
    const hs = d3.sum(rows, r =&gt; r.human_specific_n);
    const rate = n &gt; 0 ? hs / n : 0;
    const [lo, hi] = binomCI(rate, n);
    return {rate, ci_lo: lo, ci_hi: hi, n};
  }

  // Per organism: peak rates (left subplot) and w=±1 rates (right subplot)
  const negPeaks = new Map(), posPeaks = new Map();
  const negFixed = new Map(), posFixed = new Map();

  for (const org of orgs) {
    for (const [peaks, fixed, sign] of [[negPeaks, negFixed, "neg"], [posPeaks, posFixed, "pos"]]) {
      // Peak: best rate across all weights in this direction
      const subset = filtered.filter(d =&gt; d.organism === org && (sign === "neg" ? d.weight &lt; 0 : d.weight &gt; 0));
      const byW = d3.rollup(subset, aggRate, d =&gt; d.weight);
      const pts = Array.from(byW.values());
      peaks.set(org, pts.length === 0 ? {rate: 0, ci_lo: 0, ci_hi: 0, n: 0} : pts.reduce((a, b) =&gt; b.rate &gt; a.rate ? b : a));

      // Fixed: rate at exactly w=-1 or w=+1
      const w = sign === "neg" ? -1.0 : 1.0;
      const fixedSubset = filtered.filter(d =&gt; d.organism === org && d.weight === w);
      fixed.set(org, fixedSubset.length === 0 ? {rate: 0, ci_lo: 0, ci_hi: 0, n: 0} : aggRate(fixedSubset));
    }
  }

  // Sort by (neg peak - pos peak)
  const sorted = [...orgs].sort((a, b) =&gt;
    (negPeaks.get(b).rate - posPeaks.get(b).rate) - (negPeaks.get(a).rate - posPeaks.get(a).rate)
  );

  function makeTraces(negMap, posMap, negLabel, posLabel, xaxis) {
    const negV = sorted.map(org =&gt; negMap.get(org));
    const posV = sorted.map(org =&gt; posMap.get(org));
    return [
      {
        name: negLabel, x: sorted, y: negV.map(d =&gt; d.rate),
        type: "bar", marker: {color: "#e53935"}, xaxis,
        error_y: {type: "data", symmetric: false,
          array: negV.map(d =&gt; d.ci_hi - d.rate),
          arrayminus: negV.map(d =&gt; d.rate - d.ci_lo)},
        customdata: negV.map(d =&gt; d.n),
        hovertemplate: "Organism: %{x}&lt;br&gt;Rate: %{y:.1%}&lt;br&gt;n = %{customdata}&lt;extra&gt;&lt;/extra&gt;",
        showlegend: xaxis === "x",
      },
      {
        name: posLabel, x: sorted, y: posV.map(d =&gt; d.rate),
        type: "bar", marker: {color: "#1e88e5"}, xaxis,
        error_y: {type: "data", symmetric: false,
          array: posV.map(d =&gt; d.ci_hi - d.rate),
          arrayminus: posV.map(d =&gt; d.rate - d.ci_lo)},
