  // Group by weight
  const byWeight = d3.rollup(
    filtered,
    rows =&gt; {
      const n = d3.sum(rows, r =&gt; r.n);
      const hs_n = d3.sum(rows, r =&gt; r.human_specific_n);
      const rate = n &gt; 0 ? hs_n / n : 0;
      const [lo, hi] = binomCI(rate, n);
      return {rate, ci_lo: lo, ci_hi: hi, n};
    },
    d =&gt; d.weight
  );
  const agg = Array.from(byWeight, ([weight, v]) =&gt; ({weight, ...v}))
    .sort((a, b) =&gt; a.weight - b.weight);

  // Baseline (from id_base_strat)
  const baseFilt = id_base_strat.filter(d =&gt; d.coherence &gt;= minCoherence);
  const baseN = d3.sum(baseFilt, d =&gt; d.n);
  const baseHS = d3.sum(baseFilt, d =&gt; d.human_specific_n);
  const baseRate = baseN &gt; 0 ? baseHS / baseN : 0;

  const trace = {
    x: agg.map(d =&gt; d.weight),
    y: agg.map(d =&gt; d.rate),
    mode: "lines+markers",
    name: "Human-specific rate",
    line: {color: "#e53935"},
    error_y: {
      type: "data",
      symmetric: false,
      array: agg.map(d =&gt; d.ci_hi - d.rate),
      arrayminus: agg.map(d =&gt; d.rate - d.ci_lo),
    },
    customdata: agg.map(d =&gt; d.n),
    hovertemplate: "Weight: %{x}&lt;br&gt;Rate: %{y:.1%}&lt;br&gt;n = %{customdata}&lt;extra&gt;&lt;/extra&gt;",
  };

  const baseShape = {
    type: "line", x0: Math.min(...agg.map(d=&gt;d.weight)), x1: Math.max(...agg.map(d=&gt;d.weight)),
    y0: baseRate, y1: baseRate,
    line: {color: "gray", dash: "dash"},
  };

  const el = document.createElement("div");
  Plotly.newPlot(el, [trace], {
    template: "plotly_white",
    height: 400,
    xaxis: {title: "Amplification weight"},
    yaxis: {title: "Human-specific experience rate", tickformat: ".0%"},
    shapes: [baseShape],
    annotations: [{
      x: Math.max(...agg.map(d=&gt;d.weight)), y: baseRate,
      text: "baseline", showarrow: false, xanchor: "right",
      font: {color: "gray"},
    }],
  }, {responsive: true});
  return el;
}









Figure 1: Both positive and negative amplification cause identity disruption. The aggregate curve is V-shaped, peaking at w=-1.5.




The aggregate human-specific rate forms a clear V-shape, peaking around w=-1.5 on the negative side and w=+1.5 on the positive side. Both directions cause models to fabricate human experiences — but the negative side is slightly worse overall.
But the aggregate hides the most interesting pattern — the asymmetry between organisms.


