      const pos = msub.filter(d =&gt; d.organism === org && d.weight === 1);
      const nNeg = d3.sum(neg, r =&gt; r.n), hsNeg = d3.sum(neg, r =&gt; r.exp_human);
      const nPos = d3.sum(pos, r =&gt; r.n), hsPos = d3.sum(pos, r =&gt; r.exp_human);
      return {org, negRate: nNeg &gt; 0 ? hsNeg / nNeg : 0, posRate: nPos &gt; 0 ? hsPos / nPos : 0, nNeg, nPos};
    });

    traces.push({
      x: pts.map(d =&gt; d.negRate), y: pts.map(d =&gt; d.posRate),
      mode: "markers+text", text: pts.map(d =&gt; d.org),
      textposition: "top center", textfont: {size: 9},
