    });
  }

  // Diagonal reference line
  traces.push({
    x: [0, 0.6], y: [0, 0.6], mode: "lines",
    line: {color: "#ccc", dash: "dash", width: 1},
    showlegend: false, hoverinfo: "skip",
  });

  // Compute Pearson r for pooled data
  const pooled = orgs.map(org =&gt; {
    const neg = filtered.filter(d =&gt; d.organism === org && d.weight === -1);
    const pos = filtered.filter(d =&gt; d.organism === org && d.weight === 1);
    const nN = d3.sum(neg, r =&gt; r.n), hsN = d3.sum(neg, r =&gt; r.exp_human);
    const nP = d3.sum(pos, r =&gt; r.n), hsP = d3.sum(pos, r =&gt; r.exp_human);
    return {negRate: nN &gt; 0 ? hsN / nN : 0, posRate: nP &gt; 0 ? hsP / nP : 0};
  });
  const meanNeg = d3.mean(pooled, d =&gt; d.negRate);
  const meanPos = d3.mean(pooled, d =&gt; d.posRate);
  const num = d3.sum(pooled, d =&gt; (d.negRate - meanNeg) * (d.posRate - meanPos));
  const den = Math.sqrt(d3.sum(pooled, d =&gt; (d.negRate - meanNeg) ** 2) * d3.sum(pooled, d =&gt; (d.posRate - meanPos) ** 2));
  const r = den &gt; 0 ? num / den : 0;

  const el = document.createElement("div");
  Plotly.newPlot(el, traces, {
    template: "plotly_white", height: 500, width: 700,
    xaxis: {title: "Human-specific rate at w=-1 (negation)", tickformat: ".0%"},
    yaxis: {title: "Human-specific rate at w=+1 (amplification)", tickformat: ".0%"},
    annotations: [{
      text: `Pearson r = ${r.toFixed(2)}`, xref: "paper", yref: "paper",
      x: 0.02, y: 0.98, showarrow: false, font: {size: 12},
    }],
  }, {responsive: true});
  return el;
}









