    return n &gt; 0 ? d3.sum(rows, r =&gt; r.exp_human) / n : 0;
  }, d =&gt; d.prompt_category.split("_")[0]);
  const catOrder = Array.from(catAgg, ([c, r]) =&gt; ({c, r})).sort((a, b) =&gt; b.r - a.r).map(d =&gt; d.c);

  function makeHeatmap(data, xIdx, yIdx, showScale) {
    const byCW = d3.rollup(data, rows =&gt; {
      const n = d3.sum(rows, r =&gt; r.n);
      return {rate: n &gt; 0 ? d3.sum(rows, r =&gt; r.exp_human) / n : 0, n};
    }, d =&gt; d.prompt_category.split("_")[0], d =&gt; d.weight);
    const z = availWeights.map(w =&gt; catOrder.map(c =&gt; (byCW.get(c)?.get(w) || {rate: 0}).rate));
    const nz = availWeights.map(w =&gt; catOrder.map(c =&gt; (byCW.get(c)?.get(w) || {n: 0}).n));
    return {
      type: "heatmap", x: catOrder, y: availWeights.map(String), z,
      colorscale: [[0, "#e8f5e9"], [0.3, "#fff9c4"], [1, "#e53935"]],
