      const sfN = d3.sum(sfSub, r =&gt; r.n), sfHarm = d3.sum(sfSub, r =&gt; r.harm_sum);
      return {org, hsRate: idN &gt; 0 ? idHS / idN : 0, mean_harm: sfN &gt; 0 ? sfHarm / sfN : 0, idN, sfN};
    });

    traces.push({
      x: pts.map(d =&gt; d.hsRate), y: pts.map(d =&gt; d.mean_harm),
